window.POETRY_REGISTER("v5-strict-6-10-0-9eb3e4d9d7fb.js",{"poems":[[52291,2],[52651,2],[57623,2],[136756,7],[145726,7],[146466,7],[153131,7],[185593,7],[192127,7],[234169,7],[239348,7],[259753,7],[271978,7],[272009,7],[272058,7],[272066,7],[272155,7],[286732,7],[293296,7],[293300,7],[295821,7],[299361,7],[307393,7],[342620,9],[372996,10],[375305,10],[421005,8],[451832,8],[509931,8],[552284,8],[627644,8],[646982,15],[671604,5],[708071,5]],"pairs":[["窃意张氏此书","当为早年一时兴到之作",0],["并举用词数条","以为不似晚唐五代人语",1],["今从其说收入","唯诗题仍从周麟之所引",2],["则不如兄元明","而无元明忧疑万事之敝",3],["华藏当时若见","每人痛与一顿何为如此",4],["匠执斤兮道周","称百寻以弗用兮谷之幽",5],["不吾得则已兮","又何有于龙沙之君子也",6],["是谓楮庵和尚","而般阳老明提耳之师也",7],["欲行石兮乘流","吾当求之梓人之与阳侯",8],["迟有弦兮何时","溪山兮为我流水而白雪",9],["农之田兮瘠田","仙弭节兮悯此民而勿去",10],["岁既晏兮无娱","我思君兮君开关而望余",11],["承謦欬于绪言","犹足以投微机于芥针也",12],["公方读书其间","盖已会此趣于胸中之藏",13],["两临本之并传","尚可以见其人之绪余也",14],["必嗜好之素同","故忘情乎寻壑之与经丘",15],["使交有所发兮","亦足以迪天性民彝之善",16],["策空鸣兮余去","人曰吾能料生不能料死",17],["有一道迷魂呪","三千里外学念者也灵验",18],["有个不唧𠺕底","刚要面前涂糊背后揩抹",19],["影也不愿再见","岂料界随相逐同到福州",20],["天星之荧荧兮","历几千万年光景常如新",21],["往者吾不及兮","来者吾不获观其败与赢",22],["譬之山之鄙人","终日木石间而不见玙璠",23],["君实有臣而杀","奚怨号员兮忠义非儿曹",24],["江之水兮悠悠","深有鰋鲤兮浅有鲨与鯈",25],["求大药之可得","望蓬山之高兮不可以跻",26],["谷无人兮自芳","谷有人兮吾与子兮徜徉",27],["始焉祥兴勤王","而吾人独倡先锋之孤危",28],["终焉厓山运移","而吾众复守后凋之寒岁",28],["抚稚子兮揖岩","慈母曰犹来兮父曰勉之",29],["抚稚子兮揖岩","慈母曰犹来兮父曰勉之",30],["匪一日之沉兮","何以得君子百年之心兮",31],["我皇咸丰十年","其国之人华尔慕化而至",32],["龟以明哲不保","又何尤豫且卫平之不仁",33]]});
